    // for "fine-grained progress monitoring"
    const int BATCH_SIZE = 50;
    for (int start = 0; start < N; start += BATCH_SIZE) {
        int batch_n = (start + BATCH_SIZE <= N) ? BATCH_SIZE : (N - start);
        int grid = (batch_n + block - 1) / block;

        brute_nn_kernel<<<grid, block, 0, stream>>>(
            src + 3 * start, tgt, batch_n, M, d_max_sq,
            g_match_idx + start, g_centroid_acc, count_out);

        cudaDeviceSynchronize();  // ← regression: per-batch sync
    }
